/** the clips' frame rate (Wan 2.2 makes 16 frames a second); play a sequence with anim.loop(seq, t, queenFps(seq)) or anim.at(seq, p) */
export const QUEEN_ANIM_FPS = 16;
/** idle, stunned and sit keep every other clip frame, so they play at half the rate */
export const QUEEN_SEQ_FPS: Record<string, number> = { idle: 8, stunned: 8, sit: 8 };
export const queenFps = (seq: string): number => QUEEN_SEQ_FPS[seq] ?? QUEEN_ANIM_FPS;
/**
 * Each attack's readable wind-up, its strike and (for the slam) its recovery. Every tell plays for at least 0.6 s at its rate
 * (the boss fairness rule, reference/HANDOFF.md); a fight holds the tell's last frame if its tell runs longer. The game draws the silk
 * shot and the web net itself, so the strikes show her body only.
 */
export const QUEEN_MOVES = {
  silkShot: { tell: 'silkTell', act: 'silkAct' },
  legSlam: { tell: 'slamTell', act: 'slamAct', rec: 'slamRec' },
  webNet: { tell: 'netTell', act: 'netAct' },
} as const;
/** loops (idle, skitter, stunned), one-shots held at the end (hurt, defeat), and her tea-party gestures for the intro and the tea scene */
export const QUEEN_LOOPS = ['idle', 'skitter', 'stunned'] as const;
export const QUEEN_ONCE = ['hurt', 'defeat', 'sit', 'pour'] as const;
